    if not s:
        return

    nums = []
    ops = []
    i = 0
    n = len(s)

    while i < n:
        if s[i].isdigit():
            num = 0
            while i < n and s[i].isdigit():
                num = num * 10 + int(s[i])
                i += 1
            nums.append(num)
        else:
            ops.append(s[i])
            i += 1

    max_val = 0

    # Try all possible pairs (i, j) where i <= j
    # i is the index of the first number inside the brackets
    # j is the index of the last number inside the brackets
    for i in range(len(nums)):
        for j in range(i, len(nums)):
            # Construct the expression with brackets around nums[i]...nums[j]
            # Format: nums[0] op[0] ... op[i-1] ( nums[i] op[i] ... op[j-1] nums[j] ) op[j] ...

            # Part 1: Before the bracket
            if i == 0:
                part1 = ""
            else:
                part1 = str(nums[0])
                for k in range(i - 1):
                    part1 += ops[k] + str(nums[k + 1])

            # Part 2: Inside the bracket
            inner = str(nums[i])
            for k in range(i, j):
                inner += ops[k] + str(nums[k + 1])

            # Part 3: After the bracket
            if j == len(nums) - 1:
                part3 = ""
            else:
                part3 = ops[j] + str(nums[j + 1])
                for k in range(j + 1, len(nums) - 1):
                    part3 += ops[k] + str(nums[k + 1])

            # Combine
            expr = part1 + "(" + inner + ")" + part3
            val = eval(expr)
            if val > max_val:
                max_val = val

    print(max_val)

